import React from 'react';
import { useGameStore } from '../store/useGameStore';
import Cell from './Cell';
import { CELL_SIZE_MAP, CellSizeLevel, DEFAULT_GRID_SIZE } from '../utils/constants';

const Board: React.FC = () => {
  const { board, revealCell, toggleMark, gridCols, cellSizeLevel, gameMode } = useGameStore();

  if (!board || board.length === 0) return null;

  const handleContextMenu = (e: React.MouseEvent, row: number, col: number) => {
    e.preventDefault();
    toggleMark(row, col);
  };

  // 经典模式强制使用固定大小
  const isClassicMode = gameMode === 'classic';
  const effectiveGridCols = isClassicMode ? DEFAULT_GRID_SIZE : gridCols;
  
  // 获取实际的像素大小
  const cellSize = CELL_SIZE_MAP[cellSizeLevel as CellSizeLevel] || CELL_SIZE_MAP.medium;
  
  // 计算棋盘的宽度
  const boardWidth = cellSize * effectiveGridCols;
  
  // 响应式最大宽度，根据设备调整
  const maxBoardWidth = Math.min(boardWidth, 600);
  const actualCellSize = boardWidth > maxBoardWidth ? maxBoardWidth / effectiveGridCols : cellSize;
  
  // 确保格子最小18px，方便点击
  const finalCellSize = Math.max(Math.floor(actualCellSize), 18);

  return (
    <div className="flex justify-center w-full">
      <div 
        className="grid gap-0 border-2 border-gray-800 bg-gray-300 select-none"
        style={{
          gridTemplateColumns: `repeat(${effectiveGridCols}, ${finalCellSize}px)`,
          maxWidth: '100%',
          width: finalCellSize * effectiveGridCols,
          boxSizing: 'content-box'
        }}
      >
        {board.map((row, rowIndex) =>
          row.map((cell, colIndex) => (
            <Cell
              key={`${rowIndex}-${colIndex}`}
              cell={cell}
              onClick={() => revealCell(rowIndex, colIndex)}
              onContextMenu={(e) => handleContextMenu(e, rowIndex, colIndex)}
              size={finalCellSize}
            />
          ))
        )}
      </div>
    </div>
  );
};

export default Board;