import React, { useEffect, useState } from 'react';
import Board from './Board';
import Controls from './Controls';
import RulesModal from './RulesModal';
import NicknameInput from './NicknameInput';
import Leaderboard from './Leaderboard';
import { useGameStore } from '../store/useGameStore';
import { LogOut, History, RefreshCw, Settings, Trophy, HelpCircle } from 'lucide-react';
import GameHistory from './GameHistory';
import DanmuOverlay from './DanmuOverlay';
import ChallengeList from './ChallengeList';
import ChallengeCreator from './ChallengeCreator';
import { canFitAllPlanes } from '../utils/gameUtils';

const Game: React.FC = () => {
  const { 
    initGame, nickname, logout, gameMode, planeCounts, setPlaneCounts,
    gridRows, gridCols, setGridRows, setGridCols,
    cellSizeLevel, setCellSizeLevel, clicks, foundHeads, totalHeads, isGameOver, isWin,
    activeChallengeId, challenges, loadHistory
  } = useGameStore();
  
  const [isRulesOpen, setIsRulesOpen] = useState(false);
  const [isLeaderboardOpen, setIsLeaderboardOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [showDanmu, setShowDanmu] = useState(true);
  const [showSettings, setShowSettings] = useState(false);
  const [tempCounts, setTempCounts] = useState(planeCounts);
  const [tempGridRowsStr, setTempGridRowsStr] = useState(String(gridRows));
  const [tempGridColsStr, setTempGridColsStr] = useState(String(gridCols));
  
  // Challenge Mode Modals
  const [isChallengeListOpen, setIsChallengeListOpen] = useState(false);
  const [isChallengeCreatorOpen, setIsChallengeCreatorOpen] = useState(false);

  // Initialize game on mount
  useEffect(() => {
    initGame();
    loadHistory();
    // Auto open rules on first load
    setIsRulesOpen(true);
  }, [initGame, loadHistory]);

  React.useEffect(() => {
    setTempCounts(planeCounts);
    setTempGridRowsStr(String(gridRows));
    setTempGridColsStr(String(gridCols));
  }, [planeCounts, gridRows, gridCols]);

  // Auto-open challenge list if mode is challenge but no active challenge
  useEffect(() => {
      if (gameMode === 'challenge' && !activeChallengeId) {
          // Fetch challenges explicitly when switching to challenge mode
          useGameStore.getState().fetchChallenges();
          setIsChallengeListOpen(true);
      }
  }, [gameMode, activeChallengeId]);

  const handleCountChange = (index: number, value: string) => {
    const val = parseInt(value) || 0;
    const clamped = Math.max(0, Math.min(5, val));
    const newCounts = [...tempCounts];
    newCounts[index] = clamped;
    setTempCounts(newCounts);
  };

  const handleGridRowsChange = (value: string) => {
    setTempGridRowsStr(value);
  };

  const handleGridColsChange = (value: string) => {
    setTempGridColsStr(value);
  };

  const applySettings = () => {
    if (gameMode !== 'classic') {
        // 解析输入值并验证
        const rowsVal = parseInt(tempGridRowsStr) || 5;
        const colsVal = parseInt(tempGridColsStr) || 5;
        
        // 限制在有效范围内
        const finalRows = Math.max(5, Math.min(30, rowsVal));
        const finalCols = Math.max(5, Math.min(30, colsVal));
        
        // Check if we can fit all planes before applying
        if (!canFitAllPlanes(tempCounts, finalRows, finalCols)) {
            alert('棋盘太小了！至少需要 5x5 的棋盘才能放置飞机');
            return;
        }
        
        setPlaneCounts(tempCounts);
        setGridRows(finalRows);
        setGridCols(finalCols);
    }
    setShowSettings(false);
    setTimeout(() => {
        initGame();
    }, 0);
  };

  const activeChallenge = gameMode === 'challenge' ? challenges.find(c => c.id === activeChallengeId) : null;

  if (!nickname) {
    return <NicknameInput />;
  }

  return (
    <div className="flex flex-col items-center w-full max-w-4xl mx-auto gap-4 animate-in fade-in duration-500 relative py-4 px-2">
      {/* Top Right: Record and Logout */}
      <div className="absolute top-4 right-4 flex gap-2 z-10">
        <button 
            onClick={() => setIsHistoryOpen(true)}
            className="p-1.5 text-xs bg-gray-100 hover:bg-gray-200 text-gray-700 rounded flex items-center gap-1 transition-colors"
            title="游戏记录"
        >
            <History size={14} />
            <span className="hidden sm:inline">记录</span>
        </button>
        <button 
            onClick={logout}
            className="p-1.5 text-xs bg-red-50 hover:bg-red-100 text-red-600 rounded flex items-center gap-1 transition-colors"
            title="退出登录"
        >
            <LogOut size={14} />
            <span className="hidden sm:inline">退出</span>
        </button>
      </div>

      <div className="flex flex-col items-center w-full">
        <h1 className="text-2xl sm:text-3xl font-bold text-gray-800 mb-4 text-center">寻机头小游戏</h1>
        
        {/* New Game, Settings, Help Buttons */}
        <div className="flex items-center gap-2 sm:gap-3 flex-wrap justify-center">
            <button 
                onClick={initGame}
                className="flex items-center gap-2 px-3 sm:px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-colors font-medium shadow-sm active:transform active:scale-95"
            >
                <RefreshCw size={16} />
                新游戏
            </button>
            
            {gameMode === 'classic' && (
                <button 
                    onClick={() => setIsLeaderboardOpen(true)}
                    className="p-2 bg-yellow-100 hover:bg-yellow-200 rounded-lg border border-yellow-300 transition-colors"
                    title="排行榜"
                >
                    <Trophy size={18} className="text-yellow-600" />
                </button>
            )}
            
            <button 
                onClick={() => {
                    setShowSettings(!showSettings);
                    setTempCounts(planeCounts);
                    setTempGridRowsStr(String(gridRows));
                    setTempGridColsStr(String(gridCols));
                }}
                className={`p-2 rounded-lg border transition-colors font-medium shadow-sm ${
                    showSettings 
                        ? 'bg-purple-100 border-purple-300 text-purple-700' 
                        : 'bg-purple-50 hover:bg-purple-100 border-purple-200 text-purple-600'
                }`}
                title="设置"
            >
                <Settings size={18} />
            </button>
            
            <button 
                onClick={() => setIsRulesOpen(true)}
                className="p-2 bg-gray-100 hover:bg-gray-200 rounded-lg border border-gray-300 transition-colors"
                title="规则"
            >
                <HelpCircle size={18} className="text-gray-700" />
            </button>
        </div>

        {/* Settings Panel */}
        {showSettings && (
            <div className="mt-4 w-full max-w-md p-4 bg-gray-50 rounded-lg border border-gray-200 animate-in slide-in-from-top-2">
                <h3 className="font-bold mb-3 text-gray-700">设置</h3>
                
                {/* Cell Size (All Modes) */}
                <div className="mb-4">
                    <div className="text-sm font-medium text-gray-600 mb-2">格子大小</div>
                    <div className="flex gap-2 justify-center">
                        {(['small', 'medium', 'large'] as const).map((level) => (
                            <button
                                key={level}
                                onClick={() => setCellSizeLevel(level)}
                                className={`flex-1 py-2 rounded-lg text-sm font-medium transition-colors ${
                                    cellSizeLevel === level
                                        ? 'bg-blue-600 text-white'
                                        : 'bg-white border border-gray-300 text-gray-700 hover:bg-gray-100'
                                }`}
                            >
                                {level === 'small' ? '小' : level === 'medium' ? '中' : '大'}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Danmu Setting (All Modes) */}
                <div className="mb-4">
                    <div className="text-sm font-medium text-gray-600 mb-2">弹幕设置</div>
                    <div className="flex items-center justify-center gap-2">
                        <label className="flex items-center gap-2 cursor-pointer">
                            <input
                                type="checkbox"
                                checked={showDanmu}
                                onChange={(e) => setShowDanmu(e.target.checked)}
                                className="w-4 h-4"
                            />
                            <span className="text-sm text-gray-700">显示弹幕</span>
                        </label>
                    </div>
                </div>
                
                {/* Plane & Grid Size (Not Classic) */}
                {gameMode !== 'classic' && (
                    <>
                        <div className="mb-4">
                            <div className="text-sm font-medium text-gray-600 mb-2">飞机数量</div>
                            <div className="flex gap-4 justify-center">
                                {tempCounts.map((count, idx) => (
                                    <div key={idx} className="flex flex-col items-center">
                                        <span className="text-xs text-gray-500 mb-1">类型 {idx + 1}</span>
                                        <input
                                            type="number"
                                            min="0"
                                            max="5"
                                            value={count}
                                            onChange={(e) => handleCountChange(idx, e.target.value)}
                                            className="w-12 p-1 text-center border border-gray-300 rounded focus:ring-2 focus:ring-blue-500 outline-none"
                                        />
                                    </div>
                                ))}
                            </div>
                        </div>
                        
                        <div className="mb-4">
                            <div className="text-sm font-medium text-gray-600 mb-2">棋盘大小</div>
                            <div className="flex gap-4 justify-center">
                                <div className="flex flex-col items-center">
                                    <span className="text-xs text-gray-500 mb-1">行数</span>
                                    <input
                                        type="number"
                                        min="5"
                                        max="30"
                                        value={tempGridRowsStr}
                                        onChange={(e) => handleGridRowsChange(e.target.value)}
                                        className="w-12 p-1 text-center border border-gray-300 rounded focus:ring-2 focus:ring-blue-500 outline-none"
                                    />
                                </div>
                                <div className="flex flex-col items-center">
                                    <span className="text-xs text-gray-500 mb-1">列数</span>
                                    <input
                                        type="number"
                                        min="5"
                                        max="30"
                                        value={tempGridColsStr}
                                        onChange={(e) => handleGridColsChange(e.target.value)}
                                        className="w-12 p-1 text-center border border-gray-300 rounded focus:ring-2 focus:ring-blue-500 outline-none"
                                    />
                                </div>
                            </div>
                            {/* Validation warning */}
                            {(() => {
                                const rowsVal = parseInt(tempGridRowsStr) || 5;
                                const colsVal = parseInt(tempGridColsStr) || 5;
                                const finalRows = Math.max(5, Math.min(30, rowsVal));
                                const finalCols = Math.max(5, Math.min(30, colsVal));
                                return !canFitAllPlanes(tempCounts, finalRows, finalCols) && (
                                    <div className="mt-2 text-xs text-red-600 bg-red-50 p-2 rounded text-center">
                                        ⚠️ 棋盘太小！至少需要 5x5 的棋盘才能放下飞机
                                    </div>
                                );
                            })()}
                        </div>
                    </>
                )}
                
                <button 
                    onClick={applySettings}
                    className="w-full py-2 bg-gray-800 hover:bg-gray-900 text-white rounded transition-colors text-sm font-medium"
                >
                    {gameMode !== 'classic' ? '应用并开始新游戏' : '应用'}
                </button>
            </div>
        )}
      </div>
      
      <div className="w-full flex flex-col items-center gap-6 relative">
        <Controls 
          onOpenRules={() => setIsRulesOpen(true)} 
          onOpenLeaderboard={() => setIsLeaderboardOpen(true)}
          clicks={clicks}
          foundHeads={foundHeads}
          totalHeads={totalHeads}
          isGameOver={isGameOver}
          isWin={isWin}
          activeChallenge={activeChallenge}
        />
        
        {/* Challenge Action Bar if in challenge mode */}
        {gameMode === 'challenge' && (
            <div className="w-full max-w-md bg-purple-50 p-3 rounded-xl border border-purple-200 flex justify-between items-center shadow-sm">
                <div className="text-sm text-purple-800 font-medium flex items-center gap-1">
                    {activeChallengeId ? '正在进行挑战' : '请选择一个挑战'}
                </div>
                <div className="flex gap-2">
                    <button 
                        onClick={() => setIsChallengeListOpen(true)}
                        className="px-3 py-1.5 bg-white hover:bg-purple-100 text-purple-700 rounded-lg border border-purple-200 text-xs font-bold transition-colors shadow-sm"
                    >
                        更换挑战
                    </button>
                    <button 
                        onClick={() => setIsChallengeCreatorOpen(true)}
                        className="px-3 py-1.5 bg-purple-600 hover:bg-purple-700 text-white rounded-lg text-xs font-bold transition-colors shadow-sm"
                    >
                        创建挑战
                    </button>
                </div>
            </div>
        )}

        <div className="relative w-full">
            <Board />
            {showDanmu && <DanmuOverlay />}
        </div>
      </div>

      {/* Spacer for bottom input to avoid overlapping content */}
      {showDanmu && <div className="h-16 w-full shrink-0" />}

      <RulesModal isOpen={isRulesOpen} onClose={() => setIsRulesOpen(false)} />
      
      {isLeaderboardOpen && (
        <Leaderboard onClose={() => setIsLeaderboardOpen(false)} />
      )}

      {isHistoryOpen && (
        <GameHistory onClose={() => setIsHistoryOpen(false)} />
      )}
      
      {isChallengeListOpen && (
          <ChallengeList 
            onClose={() => setIsChallengeListOpen(false)} 
            onCreateNew={() => setIsChallengeCreatorOpen(true)} 
          />
      )}

      {isChallengeCreatorOpen && (
          <ChallengeCreator onClose={() => setIsChallengeCreatorOpen(false)} />
      )}

      <div className="text-sm text-gray-400 mt-8 mb-4">
        Designed by Trae
      </div>
    </div>
  );
};

export default Game;