import React from 'react';
import { useGameStore } from '../store/useGameStore';
import { Flag, MousePointerClick } from 'lucide-react';
import { PLANE_SHAPES } from '../utils/constants';

interface ControlsProps {
  onOpenRules: () => void;
  onOpenLeaderboard: () => void;
  clicks: number;
  foundHeads: number;
  totalHeads: number;
  isGameOver: boolean;
  isWin: boolean;
  activeChallenge: any;
}

const Controls: React.FC<ControlsProps> = ({ 
  onOpenRules, onOpenLeaderboard, 
  clicks, foundHeads, totalHeads, isGameOver, isWin, activeChallenge
}) => {
  const { 
    planeCounts, gameMode, setGameMode,
    isMarkMode, toggleMarkMode
  } = useGameStore();

  return (
    <div className="w-full max-w-md bg-white p-3 sm:p-4 rounded-xl shadow-md border border-gray-100">
      
      {/* Mode Switcher */}
      <div className="flex bg-gray-100 p-1 rounded-lg mb-4">
        <button
          onClick={() => setGameMode('classic')}
          className={`flex-1 py-1.5 text-xs sm:text-sm font-medium rounded-md transition-all ${
            gameMode === 'classic' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'
          }`}
        >
          经典
        </button>
        <button
          onClick={() => setGameMode('custom')}
          className={`flex-1 py-1.5 text-xs sm:text-sm font-medium rounded-md transition-all ${
            gameMode === 'custom' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'
          }`}
        >
          自定义
        </button>
        <button
          onClick={() => setGameMode('challenge')}
          className={`flex-1 py-1.5 text-xs sm:text-sm font-medium rounded-md transition-all ${
            gameMode === 'challenge' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'
          }`}
        >
          挑战
        </button>
      </div>

      <div className="flex items-center gap-3 mb-4 flex-wrap justify-center">
        {/* Mode Toggle Button */}
        <button 
          onClick={toggleMarkMode}
          className={`flex flex-col items-center justify-center w-10 h-10 sm:w-12 sm:h-12 rounded-xl transition-colors font-medium shadow-sm active:transform active:scale-95 border-2 flex-shrink-0 ${
            isMarkMode 
              ? 'bg-red-50 text-red-600 border-red-200' 
              : 'bg-blue-50 text-blue-600 border-blue-200 hover:bg-blue-100'
          }`}
          title={isMarkMode ? "切换为点击模式" : "切换为标记模式"}
        >
          {isMarkMode ? <Flag size={16} className="sm:w-5 sm:h-5" /> : <MousePointerClick size={16} className="sm:w-5 sm:h-5" />}
          <span className="text-[8px] sm:text-[10px] mt-0.5">{isMarkMode ? '标记' : '点击'}</span>
        </button>
        
        {/* Stats */}
        <div className="flex-shrink-0 text-left">
          <div className="text-xs sm:text-sm font-semibold text-gray-700">
            点击: <span className="text-blue-600">{clicks}</span>
          </div>
          <div className="text-xs sm:text-sm font-semibold text-gray-700">
            机头: <span className="text-green-600">{foundHeads}/{totalHeads}</span>
          </div>
          {activeChallenge && (
            <div className="text-[10px] sm:text-xs text-gray-500 mt-1">
              🏆 {activeChallenge.best_solver_nickname ? `${activeChallenge.best_solver_nickname} (${activeChallenge.best_solver_clicks}步)` : '暂无人'}
            </div>
          )}
        </div>
        
        {/* Separator - only on larger screens */}
        <div className="hidden sm:block w-px h-10 bg-gray-200 mx-1"></div>
        
        {/* Plane Shapes Display */}
        <div className="flex gap-2 sm:gap-3 flex-wrap items-center justify-center">
          {PLANE_SHAPES.map((shape, index) => {
            if (planeCounts[index] === 0) return null;
            return (
              <div key={index} className="flex flex-col items-center group">
                <div className="grid grid-cols-5 gap-px border border-gray-200 bg-white p-1 shadow-sm group-hover:shadow-md transition-shadow">
                  {shape.flat().map((cell, cIndex) => (
                    <div 
                      key={cIndex} 
                      className={`w-1 h-1 sm:w-1.5 sm:h-1.5 rounded-[1px] ${cell === 2 ? 'bg-red-500' : cell === 1 ? 'bg-blue-500' : 'invisible'}`}
                    />
                  ))}
                </div>
                <span className="text-[10px] sm:text-xs text-gray-400 mt-1 font-mono">x{planeCounts[index]}</span>
              </div>
            );
          })}
        </div>
      </div>

      {isGameOver && (
        <div className={`p-3 rounded-lg text-center font-bold text-white mb-4 shadow-sm animate-in zoom-in-95 ${isWin ? 'bg-green-500' : 'bg-red-500'}`}>
          {isWin ? '🎉 恭喜你找到了所有机头！' : '游戏结束'}
          {isWin && gameMode === 'classic' && (
             <div className="text-xs font-normal mt-1 opacity-90">成绩已记录到排行榜</div>
          )}
          {isWin && gameMode === 'challenge' && (
             <div className="text-xs font-normal mt-1 opacity-90">你的挑战成绩已更新！</div>
          )}
        </div>
      )}
    </div>
  );
};

export default Controls;