import React, { useState } from 'react';
import { X, Play, Calendar, Trophy, Skull, Video, Download, Square, History as HistoryIcon } from 'lucide-react';
import { useGameStore, GameRecord, GameMove } from '../store/useGameStore';
import { GRID_SIZE } from '../utils/constants';

interface GameHistoryProps {
  onClose: () => void;
}

const GameHistory: React.FC<GameHistoryProps> = ({ onClose }) => {
  const { history } = useGameStore();
  const [selectedGame, setSelectedGame] = useState<GameRecord | null>(null);

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 animate-in fade-in duration-200" onClick={onClose}>
      <div className="bg-white rounded-2xl w-full max-w-4xl max-h-[90vh] shadow-2xl flex overflow-hidden relative" onClick={e => e.stopPropagation()}>
        
        {/* Close Button (Desktop) */}
        <button 
            onClick={onClose}
            className="absolute top-4 right-4 p-2 bg-gray-100 hover:bg-gray-200 rounded-full z-10 hidden md:block transition-colors"
        >
            <X size={20} className="text-gray-600" />
        </button>

        {/* Left: History List */}
        <div className={`flex flex-col border-r border-gray-100 bg-gray-50 w-full ${selectedGame ? 'hidden md:flex md:w-1/3' : 'w-full'}`}>
          <div className="p-4 border-b border-gray-200 flex justify-between items-center bg-white">
            <h2 className="text-lg font-bold text-gray-800 flex items-center gap-2">
              <Calendar className="text-blue-600" size={20} />
              游戏记录
            </h2>
            <button onClick={onClose} className="p-1 hover:bg-gray-100 rounded-full md:hidden">
              <X size={20} />
            </button>
          </div>
          
          <div className="overflow-y-auto flex-1 p-2 space-y-2">
            {history.length === 0 ? (
                <div className="text-center py-10 text-gray-400">暂无游戏记录</div>
            ) : (
                history.map((game) => (
                <div 
                    key={game.id}
                    onClick={() => setSelectedGame(game)}
                    className={`p-3 rounded-xl cursor-pointer transition-all border ${
                    selectedGame?.id === game.id 
                        ? 'bg-blue-50 border-blue-200 shadow-sm' 
                        : 'bg-white border-transparent hover:border-gray-200 hover:shadow-sm'
                    }`}
                >
                    <div className="flex justify-between items-start mb-1">
                        <span className={`text-xs px-2 py-0.5 rounded-full ${game.isWin ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                            {game.isWin ? '胜利' : '失败'}
                        </span>
                        <span className="text-xs text-gray-400">
                            {new Date(game.timestamp).toLocaleString()}
                        </span>
                    </div>
                    <div className="flex justify-between items-center mt-2">
                        <div className="text-sm font-medium text-gray-700">
                            {game.mode === 'classic' ? '经典模式' : '自定义模式'}
                        </div>
                        <div className="text-sm font-bold text-gray-900">
                            {game.clicks} 步
                        </div>
                    </div>
                </div>
                ))
            )}
          </div>
        </div>

        {/* Right: Replay View */}
        <div className={`flex-col flex-1 bg-white ${selectedGame ? 'flex' : 'hidden md:flex items-center justify-center'}`}>
          {selectedGame ? (
            <ReplayView game={selectedGame} onBack={() => setSelectedGame(null)} onClose={onClose} />
          ) : (
            <div className="text-gray-400 flex flex-col items-center">
                <HistoryIcon size={48} className="mb-4 opacity-20" />
                <p>选择一局游戏进行复盘</p>
            </div>
          )}
        </div>

      </div>
    </div>
  );
};

// Replay Component
const ReplayView: React.FC<{ game: GameRecord; onBack: () => void; onClose: () => void }> = ({ game, onBack, onClose }) => {
    const [currentStep, setCurrentStep] = useState(0);
    const [isPlaying, setIsPlaying] = useState(false);
    const [isRecording, setIsRecording] = useState(false);
    const [recordedVideoUrl, setRecordedVideoUrl] = useState<string | null>(null);
    const boardRef = React.useRef<HTMLDivElement>(null);
    const mediaRecorderRef = React.useRef<MediaRecorder | null>(null);
    const chunksRef = React.useRef<Blob[]>([]);
    
    // Auto play
    React.useEffect(() => {
        let timer: NodeJS.Timeout;
        if (isPlaying && currentStep < game.moves.length) {
            timer = setTimeout(() => {
                setCurrentStep(prev => prev + 1);
            }, 500);
        } else if (isPlaying && currentStep >= game.moves.length) {
            // Reached the end
            if (isRecording) {
                // Give it a short delay to capture the final revealed board before stopping
                timer = setTimeout(() => {
                    stopRecording();
                }, 1500); // 1.5 seconds delay at the end
            } else {
                // When playing normally (not recording), auto-pause at the end
                setIsPlaying(false);
            }
        }
        return () => clearTimeout(timer);
    }, [isPlaying, currentStep, game.moves.length, isRecording]);

    const startRecording = async () => {
        try {
            // Reset state
            setCurrentStep(0);
            setRecordedVideoUrl(null);
            chunksRef.current = [];

            // We need to capture the screen. 
            // In modern browsers, we can use navigator.mediaDevices.getDisplayMedia
            // However, this prompts the user to select a window/screen.
            // Since we just want to record the replay, we ask the user to select the current browser tab.
            const stream = await navigator.mediaDevices.getDisplayMedia({
                video: {
                    displaySurface: "browser",
                },
                audio: false,
                preferCurrentTab: true // Hint to the browser to prefer recording the current tab
            } as any);

            const mediaRecorder = new MediaRecorder(stream, { mimeType: 'video/webm' });
            mediaRecorderRef.current = mediaRecorder;

            mediaRecorder.ondataavailable = (e) => {
                if (e.data.size > 0) {
                    chunksRef.current.push(e.data);
                }
            };

            mediaRecorder.onstop = () => {
                const blob = new Blob(chunksRef.current, { type: 'video/webm' });
                const url = URL.createObjectURL(blob);
                setRecordedVideoUrl(url);
                // Stop all tracks to end screen sharing
                stream.getTracks().forEach(track => track.stop());
                setIsRecording(false);
            };

            // Start recording and playing
            mediaRecorder.start();
            setIsRecording(true);
            
            // Wait a brief moment for the recorder to initialize, then start playback
            setTimeout(() => {
                setIsPlaying(true);
            }, 500);

        } catch (err) {
            console.error("Failed to start recording:", err);
            alert("无法启动屏幕录制，请确保您授予了相应的权限，并选择录制当前标签页。");
            setIsRecording(false);
        }
    };

    const stopRecording = () => {
        if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
            mediaRecorderRef.current.stop();
        }
        setIsPlaying(false);
    };

    // Reconstruct board state at current step
    const getBoardState = () => {
        // Initialize empty board
        const board = Array.from({ length: GRID_SIZE }, (_, r) =>
            Array.from({ length: GRID_SIZE }, (_, c) => ({
                row: r, col: c, type: 'empty', revealed: false, marked: false
            }))
        );

        // Apply moves up to current step
        for (let i = 0; i < currentStep; i++) {
            const move = game.moves[i];
            if (move) {
                if (move.result === 'mark') {
                    board[move.row][move.col].marked = true;
                } else if (move.result === 'unmark') {
                    board[move.row][move.col].marked = false;
                } else {
                    board[move.row][move.col].revealed = true;
                    // Mapping result string to internal type (though it matches)
                    if (move.result === 'head') board[move.row][move.col].type = 'head';
                    else if (move.result === 'body') board[move.row][move.col].type = 'body';
                    else board[move.row][move.col].type = 'empty';
                }
            }
        }

        // If at the very end of the replay and it was a win, show all remaining planes (if boardConfig is available)
        if (currentStep >= game.moves.length && game.isWin && game.boardConfig) {
            game.boardConfig.forEach(cell => {
                if (!board[cell.row][cell.col].revealed) {
                    board[cell.row][cell.col].revealed = true;
                    board[cell.row][cell.col].type = cell.type;
                    // Let's just reveal the underlying type.
                }
            });
        }

        return board;
    };

    const boardState = getBoardState();
    const { leaderboard, nickname } = useGameStore();

    // Find ranking for this game if it was a win in classic mode
    let rankInfo = null;
    let stepInfo = null;
    if (game.mode === 'classic' && game.isWin) {
        const sortedLeaderboard = [...leaderboard].sort((a, b) => a.score - b.score);
        // Find the user's best record in the leaderboard
        const userBestIndex = sortedLeaderboard.findIndex(entry => entry.nickname === (game.nickname || nickname));
        
        if (userBestIndex !== -1) {
            rankInfo = `您的最佳记录：第 ${userBestIndex + 1} 名`;
            stepInfo = `${sortedLeaderboard[userBestIndex].score}步`;
        }
    } else if (game.mode === 'challenge' && game.isWin) {
        rankInfo = `挑战模式通关`;
    }

    return (
        <div className="flex flex-col h-full relative">
            <div className="p-4 border-b border-gray-100 flex justify-between items-center">
                <button onClick={onBack} className="md:hidden p-2 text-gray-500 hover:bg-gray-100 rounded-lg">
                    ← 返回
                </button>
                <h3 className="font-bold text-gray-800">
                    复盘 ({currentStep}/{game.moves.length} 步)
                </h3>
                <button onClick={onClose} className="p-2 text-gray-500 hover:bg-gray-100 rounded-lg">
                    <X size={20} />
                </button>
            </div>

            <div className="flex-1 overflow-auto p-4 flex flex-col items-center justify-center bg-gray-50 relative" ref={boardRef}>
                 {/* Ranking Overlay (Visible during replay/recording) */}
                 {rankInfo && (
                     <div className="absolute top-8 right-8 bg-black/70 text-yellow-400 font-bold px-4 py-3 rounded-xl shadow-lg border border-yellow-500/30 backdrop-blur-sm z-10 animate-in fade-in slide-in-from-top-4">
                         <div className="text-xs text-white/80 mb-1">{game.nickname || nickname} 的精彩对局</div>
                         <div className="text-md flex items-center gap-2">
                             <Trophy size={16} /> {rankInfo}{stepInfo ? `，${stepInfo}` : ''}
                         </div>
                         <div className="text-xs text-white/60 mt-1">当前对局: {game.clicks} 步</div>
                     </div>
                 )}

                 <div 
                      className="grid gap-0 border-2 border-gray-800 bg-gray-300 select-none shadow-xl"
                      style={{
                        gridTemplateColumns: `repeat(${GRID_SIZE}, minmax(0, 1fr))`,
                        gridTemplateRows: `repeat(${GRID_SIZE}, minmax(0, 1fr))`,
                        width: '100%',
                        maxWidth: '400px',
                        aspectRatio: '1/1'
                      }}
                    >
                      {boardState.map((row, r) =>
                        row.map((cell, c) => (
                          <div
                            key={`${r}-${c}`}
                            className={`
                                relative w-full h-full border border-gray-400
                                ${cell.revealed 
                                    ? cell.type === 'head' ? 'bg-red-500' 
                                    : cell.type === 'body' ? 'bg-blue-500' 
                                    : 'bg-gray-200'
                                : 'bg-white'}
                            `}
                          >
                            {!cell.revealed && cell.marked && (
                                <div className="absolute inset-0 flex items-center justify-center">🚩</div>
                            )}
                          </div>
                        ))
                      )}
                    </div>
            </div>

            <div className="p-4 border-t border-gray-100 bg-white">
                <div className="flex items-center gap-4 justify-center flex-wrap">
                    <button 
                        onClick={() => setCurrentStep(Math.max(0, currentStep - 1))}
                        disabled={currentStep === 0 || isRecording}
                        className="p-2 rounded-full hover:bg-gray-100 disabled:opacity-30"
                    >
                        Prev
                    </button>
                    <button 
                        onClick={() => setIsPlaying(!isPlaying)}
                        disabled={isRecording}
                        className="flex items-center gap-2 px-6 py-2 bg-blue-600 text-white rounded-full hover:bg-blue-700 transition-colors disabled:opacity-50"
                    >
                        {isPlaying ? 'Pause' : 'Play'} <Play size={16} fill="currentColor" />
                    </button>
                    <button 
                        onClick={() => setCurrentStep(Math.min(game.moves.length, currentStep + 1))}
                        disabled={currentStep === game.moves.length || isRecording}
                        className="p-2 rounded-full hover:bg-gray-100 disabled:opacity-30"
                    >
                        Next
                    </button>
                    
                    <div className="w-px h-8 bg-gray-200 mx-2"></div>

                    {/* Recording Controls */}
                    {!isRecording && !recordedVideoUrl && (
                        <button 
                            onClick={startRecording}
                            className="flex items-center gap-2 px-4 py-2 bg-purple-100 text-purple-700 hover:bg-purple-200 rounded-lg transition-colors font-medium text-sm"
                            title="录制复盘视频"
                        >
                            <Video size={16} /> 录制视频
                        </button>
                    )}
                    
                    {isRecording && (
                        <button 
                            onClick={stopRecording}
                            className="flex items-center gap-2 px-4 py-2 bg-red-100 text-red-700 hover:bg-red-200 rounded-lg transition-colors font-medium text-sm animate-pulse"
                        >
                            <Square size={16} fill="currentColor" /> 停止录制
                        </button>
                    )}

                    {recordedVideoUrl && !isRecording && (
                        <div className="flex items-center gap-2">
                            <a 
                                href={recordedVideoUrl}
                                download={`寻机头复盘_${game.nickname || nickname}_${new Date().getTime()}.webm`}
                                className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white hover:bg-green-700 rounded-lg transition-colors font-medium text-sm shadow-sm"
                            >
                                <Download size={16} /> 下载视频
                            </a>
                            <button 
                                onClick={() => setRecordedVideoUrl(null)}
                                className="text-xs text-gray-500 hover:text-gray-700 underline"
                            >
                                重新录制
                            </button>
                        </div>
                    )}
                </div>
                <div className="mt-4">
                    <input 
                        type="range" 
                        min="0" 
                        max={game.moves.length} 
                        value={currentStep} 
                        onChange={(e) => setCurrentStep(parseInt(e.target.value))}
                        disabled={isRecording}
                        className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer disabled:opacity-50"
                    />
                </div>
            </div>
        </div>
    );
};

export default GameHistory;